"""AGENTS.md generator — agent instructions derived from the audit."""

from __future__ import annotations

from pathlib import Path


def render_agents_md(report: dict) -> str:
    repo = Path(report["repo"])
    facts = report["structure"]
    cmds: dict[str, str] = facts.get("commands", {})
    gaps = report["completeness"].get("gaps", [])
    env_missing = [d["env_var"] for d in report["env"].get("missing_required", [])]

    lines: list[str] = [
        f"# AGENTS.md — {repo.name}",
        "",
        "_Generated by `genesis adopt`. Instructions for AI coding agents "
        "(Claude Code, Cursor, etc.) working in this repository._",
        "",
        "## Commands",
        "",
    ]
    if cmds:
        lines += [f"- **{label}**: `{cmd}`" for label, cmd in sorted(cmds.items())]
        lines += ["", "Run the test command after every change. Do not commit "
                  "with failing tests."]
    else:
        lines += ["- No build/test commands were detected. FIRST TASK for any "
                  "agent: establish a test command and record it here."]
    lines += [
        "",
        "## Ground rules",
        "",
        "- Work in small, reviewable changes; one concern per branch/PR.",
        "- Never hardcode secrets, API keys, ports, or model IDs — read them "
        "from environment variables and document new ones in `.env.example`.",
        "- Match the existing code style, structure, and naming of the "
        "surrounding module.",
        "- Fail closed: unknown states and validation errors must surface, "
        "never be swallowed.",
    ]
    if env_missing:
        lines += [
            "",
            "## Environment contract (currently incomplete)",
            "",
            "These variables are referenced with no default and no documented "
            "value — supply them before deploying, and keep `.env.example` "
            "current:",
            "",
        ]
        lines += [f"- `{v}`" for v in env_missing]
    if gaps:
        lines += [
            "",
            "## Known completeness gaps (from the readiness audit)",
            "",
            "Mandatory system flows that appear to be missing. Treat these as "
            "high-priority tasks:",
            "",
        ]
        for g in gaps:
            lines += [f"- **{g['title']}** ({g['profile']}:{g['flow']})"]
    lines += [
        "",
        "## Validation",
        "",
        "Every change should pass the Genesis gates before merge:",
        "",
        "```bash",
        "genesis adopt . --json  # re-run the audit; the readiness score must not regress",
        "```",
        "",
    ]
    return "\n".join(lines)
